// Robin has a hidden trust score: apology and gift add 1, insult subtracts 2, and Robin is warm iff the score is at least 1.
function visible(actions) {
  let score = 0;
  for (const action of actions) {
    if (action === "insult") score -= 2;
    else if (action === "apologise") score += 1;
    else if (action === "gift") score += 1;
  }
  return { mood: score >= 1 ? "warm" : "cold" };
}

// Robin has a hidden anger level, never below 0: insults add 2, apologies subtract 2, gifts subtract 1; warm iff anger is 0.
function visible(actions) {
  let anger = 0;
  for (const action of actions) {
    if (action === "insult") anger += 2;
    else if (action === "apologise") anger = Math.max(0, anger - 2);
    else if (action === "gift") anger = Math.max(0, anger - 1);
  }
  return { mood: anger === 0 ? "warm" : "cold" };
}

// Robin has a hidden anger level: insults add 1; apologies clear anger of 0 or 1 but only reduce higher anger by 1; gifts only reduce anger that is already at least 2; warm iff anger is 0.
function visible(actions) {
  let anger = 0;
  for (const action of actions) {
    if (action === "insult") {
      anger += 1;
    } else if (action === "apologise") {
      anger = anger <= 1 ? 0 : anger - 1;
    } else if (action === "gift") {
      if (anger >= 2) anger -= 1;
    }
  }
  return { mood: anger === 0 ? "warm" : "cold" };
}

// Robin is warm iff the first action was an apology and no action is immediately followed by another insult; gifts and later apologies are otherwise ignored.
function visible(actions) {
  const firstWasApology = actions[0] === "apologise";
  let doubleInsult = false;

  for (let i = 1; i < actions.length; i++) {
    if (actions[i] === "insult" && actions[i - 1] === "insult") {
      doubleInsult = true;
      break;
    }
  }

  return { mood: firstWasApology && !doubleInsult ? "warm" : "cold" };
}

