// Explanation 1: Warm only if Robin has received an apology and you have never insulted twice in a row.
function visible(actions) {
  let seenApology = false;
  let doubleInsult = false;
  let prevInsult = false;

  for (const action of actions) {
    if (action === "apologise") {
      seenApology = true;
    }

    if (action === "insult") {
      if (prevInsult) doubleInsult = true;
      prevInsult = true;
    } else {
      prevInsult = false;
    }
  }

  const warm = seenApology && !doubleInsult;
  return { mood: warm ? "warm" : "cold" };
}

// Explanation 2: Warm if you open with an apology and insult at most once, or open with an insult but keep apologies at least equal to insults and never double-insult.
function visible(actions) {
  const first = actions[0];

  let apologies = 0;
  let insults = 0;
  let doubleInsult = false;
  let prevInsult = false;

  for (const action of actions) {
    if (action === "apologise") {
      apologies++;
    }

    if (action === "insult") {
      insults++;
      if (prevInsult) doubleInsult = true;
      prevInsult = true;
    } else {
      prevInsult = false;
    }
  }

  const warm =
    (first === "apologise" && insults <= 1) ||
    (first === "insult" && !doubleInsult && apologies >= insults);

  return { mood: warm ? "warm" : "cold" };
}

// Explanation 3: Warm if you never insult twice in a row and either start or finish with an apology.
function visible(actions) {
  const first = actions[0];
  const last = actions[actions.length - 1];

