  for (const action of actions) {
    if (action === "insult") {
      if (prevInsult) doubleInsult = true;
      prevInsult = true;
    } else {
      prevInsult = false;
    }
  }

  const warm = !doubleInsult && (first === "apologise" || last === "apologise");
  return { mood: warm ? "warm" : "cold" };
}

